param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][string]$RomPath,[string]$ExcludedRunDirectory)
$ErrorActionPreference='Stop';$target="$PSScriptRoot/../evidence/mpu4/skill-cash";if((Get-Content "$RunDirectory/exit-code.txt" -Raw).Trim() -ne '0'){throw 'Capture incomplete'};if((Get-FileHash $RomPath -Algorithm SHA1).Hash -ne '402D1518BB78FDC489B06C2AABC771E5CE151847'){throw 'Unexpected ROM'}
$rom=[IO.File]::ReadAllBytes($RomPath);$cases=@(Get-Content "$RunDirectory/cases.json" -Raw|ConvertFrom-Json);$rows=[Collections.Generic.List[object]]::new();$active=$null
foreach($line in (Get-Content "$RunDirectory/debug.log")){if($line -notmatch '^K([SIF]) '){continue};$kind=$Matches[1];$fields=@{};foreach($match in [regex]::Matches($line,'([a-z0-9_]+)=([0-9A-F]+)')){$fields[$match.Groups[1].Value]=[Convert]::ToUInt64($match.Groups[2].Value,16)}
 if($kind -eq 'S'){if($null -ne $active){throw 'Unfinished case'};$active=[ordered]@{case=$cases[[int]$fields.id];instructions=[Collections.Generic.List[object]]::new()}}
 if($null -eq $active -or $fields.id -ne $active.case.id){throw 'Mismatched case'}
 if($kind -in @('S','I')){if($line -notmatch 'bytes=([0-9A-F]{10})'){throw 'Missing context'};$hex=$Matches[1];$pc=[int]$fields.pc;for($n=0;$n -lt 5;$n++){if([Convert]::ToByte($hex.Substring($n*2,2),16) -ne $rom[$pc+$n]){throw 'ROM context differs'}};$active.instructions.Add([ordered]@{pc=$pc;cycle=$fields.cycle;context_hex=$hex})}
 else{if($fields.pc -ne 0x2851 -or $fields.s -ne 0x700){throw 'Unexpected boundary/stack'};$active['end']=$fields;$active.instructions=@($active.instructions.ToArray());$rows.Add($active);$active=$null}}
if($null -ne $active -or $rows.Count -ne 64 -or $cases.Count -ne 64){throw 'Truncated capture'}
[ordered]@{classification='Synthetic bounded280F..2851 calls with original ROM; five-byte contexts are not instruction lengths.';native_regions=@([ordered]@{address=0x280F;bytes_hex=[Convert]::ToHexString($rom[0x280F..0x2850])});rows=@($rows.ToArray())}|ConvertTo-Json -Depth 8|Set-Content "$target/post-panel-timing.json"
[ordered]@{source_run=$RunDirectory;debug_sha256=(Get-FileHash "$RunDirectory/debug.log").Hash;cases_sha256=(Get-FileHash "$RunDirectory/cases.json").Hash;rom_sha1=(Get-FileHash $RomPath -Algorithm SHA1).Hash;provenance=(Get-Content "$RunDirectory/provenance.json" -Raw|ConvertFrom-Json);cases=$rows.Count}|ConvertTo-Json -Depth 5|Set-Content "$target/post-panel-timing-verification.json";Write-Output 'Curated64 native counter/sense calls'
if($ExcludedRunDirectory){$v=Get-Content "$target/post-panel-timing-verification.json" -Raw|ConvertFrom-Json;$v|Add-Member -NotePropertyName excluded -NotePropertyValue ([ordered]@{source_run=$ExcludedRunDirectory;debug_sha256=(Get-FileHash "$ExcludedRunDirectory/debug.log").Hash;reason='Initial debugger injection used b@A/b@B, interpreted as register addresses instead of literal RAM0A/0B. Invalid matrix; replaced with explicit0x addresses.'});$v|ConvertTo-Json -Depth 6|Set-Content "$target/post-panel-timing-verification.json"}
